__mod["controller"] = function(...)
-- Wires timer, split list, autosplitter, storage, UI and run events to the Uzume plugin API.
local fmt = require("fmt")
local model = require("model")
local rules = require("rules")
local textio = require("textio")
local timer = require("timer")
local util = require("util")
local views = require("views")

local App = {}
App.__index = App

local CORE_ID = "uzume.soullink-core" -- soft dependency: events by id, interface through fb.call when available
local BADGE_POLL_TICKS = 15
local PANEL_REFRESH_TICKS = 10

-- Frame rate guesses per system (the API has no frame rate; the user can change it in the editor).
local DEFAULT_FPS = { ["3ds"] = 59.83, nds = 59.83, gba = 59.73, gb = 59.73, gbc = 59.73 }

local function default_fps(system)
  return DEFAULT_FPS[system] or 60
end

--- Store key for the split list of a game: "splits.<game code>" (lower case, only [a-z0-9_.-]).
function App.store_key(game)
  local code = game and game.code
  if type(code) ~= "string" or code == "" then return nil end
  code = code:lower():gsub("[^a-z0-9_.-]", "_")
  return "splits." .. code:sub(1, 50)
end

function App.new(fb)
  local self = setmetatable({}, App)
  self.fb = fb
  self.T = function(key, vars) return fb.i18n.t(key, vars) end
  self.timer = timer.new()
  self.tab = 1
  self.ticks = 0
  self.names_seen = {}
  self.rev = 0
  self.shown = {}
  return self
end

function App:frame()
  return self.fb.memory.frame() or self.last_frame
end

--- Brings the timer up to date with the latest snapshot frame and clock.
function App:sync()
  self.timer:update(self:frame(), self.fb.clock())
end

function App:notify(tone, title, body)
  pcall(self.fb.ui.notify, { tone = tone, title = title, text = body })
end

-- Storage -------------------------------------------------------------------------------------------------

function App:load()
  self.list, self.rev = nil, 0
  if not self.key then return end
  local value, rev = nil, 0
  if self.fb.store then
    local ok, v, r = pcall(self.fb.store.get, self.key)
    if ok then value, rev = v, r or 0 else self.fb.log.warn("store.get failed: " .. tostring(v)) end
  end
  self.rev = rev
  self.list = model.sanitize(value) or model.new_list("game", default_fps(self.fb.game.system))
end

function App:save()
  if not self.key or not self.list or not self.fb.store then return end
  local ok, res, why = pcall(self.fb.store.put, self.key, self.list, self.rev)
  if not ok then
    self.fb.log.warn("store.put failed: " .. tostring(res))
    self:notify("warning", self.T("store.failed.title"), self.T("store.failed.text"))
  elseif res == true then
    self.rev = why
  elseif why == "conflict" then
    self:notify("warning", self.T("store.conflict.title"), self.T("store.conflict.text"))
    self.stale = true
    self:reload_if_idle()
  else
    self.fb.log.warn("store.put refused: " .. tostring(why))
    self:notify("warning", self.T("store.failed.title"), self.T("store.failed.text"))
  end
end

--- Takes the stored version when nothing is running (a running attempt keeps its list until reset).
function App:reload_if_idle()
  if not self.stale then return end
  local st = self.timer.state
  if st == "running" or st == "paused" then return end
  self.stale = false
  self:load()
  self.att = nil
  self.draft = nil
  self:render_all()
end

-- Lifecycle -----------------------------------------------------------------------------------------------

function App:start()
  local fb = self.fb
  self.key = App.store_key(fb.game)
  self:load()
  fb.on_tick(function(frame) self:tick(frame) end)
  fb.ui.on_action(function(a, v, s) self:action(a, v, s) end)
  fb.events.on(CORE_ID, "location.changed", function(v) self:on_location(v) end)
  fb.events.on("app", "store.changed", function(k)
    if k == self.key then
      self.stale = true
      self:reload_if_idle()
    end
  end)
  fb.events.on("app", "store.conflict", function(k)
    if k == self.key then
      self:notify("warning", self.T("store.conflict.title"), self.T("store.conflict.text"))
    end
  end)
  self:render_all()
end

-- Timer actions -------------------------------------------------------------------------------------------

function App:arm()
  if self.timer.state ~= "running" or not self.att then
    rules.disarm(self.fb)
    self.rule_state = nil
    return
  end
  local split = self.list.splits[model.current_index(self.att)]
  self.rule_state = rules.arm(self.fb, split and split.rule)
end

function App:start_run()
  if not self.list or #self.list.splits == 0 then return end
  self.att = model.new_attempt()
  self.result = nil
  self.backup = nil
  self.timer:start(self:frame(), self.fb.clock())
  self.list.attempts = self.list.attempts + 1
  self:save()
  self:arm()
end

function App:do_split()
  local list, att = self.list, self.att
  self.timer:update(self:frame(), self.fb.clock())
  local ms = self.timer:ms(list.timing, list.fps)
  if model.record_split(list, att, ms) then
    self:finish()
  else
    self:arm()
  end
end

function App:finish()
  local list, att = self.list, self.att
  local set = model.set(list)
  self.backup = { pb = util.copy(set.pb), golds = util.copy(set.golds), completed = list.completed }
  self.timer:stop(self:frame(), self.fb.clock())
  local info = model.commit(list, att, true)
  self.result = { total = info.total, old_total = info.old_total, pb = info.pb }
  self:save()
  self:arm()
  if info.pb then self:post_pb(info) end
end

--- Run event "splits.pb" (a note in the run recap) when a run is open in the game.
function App:post_pb(info)
  local fb = self.fb
  if not fb.run or not fb.run.event then return end
  local ok, cur = pcall(fb.run.current)
  if not ok or not cur then return end
  local text = self.T("event.pb", { time = fmt.time(info.total) })
  local ok2, res, why = pcall(fb.run.event, {
    type = "splits.pb", text = text, source = "automatic",
    payload = { total_ms = info.total, timing = self.list.timing, splits = #self.list.splits },
  })
  if not ok2 then
    fb.log.warn("run event failed: " .. tostring(res))
  elseif res == nil then
    fb.log.info("run event refused: " .. tostring(why))
  end
end

function App:split_key()
  local st = self.timer.state
  if st == "idle" then
    self:start_run()
  elseif st == "running" then
    self:do_split()
  end
end

function App:undo()
  local st = self.timer.state
  if not self.att then return end
  if st == "finished" then
    if self.backup then
      local set = model.set(self.list)
      set.pb, set.golds, self.list.completed = self.backup.pb, self.backup.golds, self.backup.completed
      self.backup = nil
      self:save()
    end
    model.undo(self.att)
    self.result = nil
    self.timer:continue(self:frame(), self.fb.clock())
    self:arm()
  elseif st == "running" or st == "paused" then
    if model.undo(self.att) then self:arm() end
  end
end

function App:skip()
  if self.timer.state == "running" and model.record_skip(self.list, self.att) then self:arm() end
end

function App:reset()
  local st = self.timer.state
  if st == "idle" then return end
  if st ~= "finished" then
    model.commit(self.list, self.att, false) -- best segments of an unfinished attempt still count
  end
  self.timer:reset()
  self.att, self.result, self.backup = nil, nil, nil
  self:save()
  self:arm()
  self:reload_if_idle()
end

function App:pause()
  local st = self.timer.state
  if st == "running" then
    self.timer:pause(self:frame(), self.fb.clock())
    rules.disarm(self.fb)
    self.rule_state = nil
  elseif st == "paused" then
    self.timer:resume(self:frame(), self.fb.clock())
    self:arm()
  end
end

-- Autosplitter --------------------------------------------------------------------------------------------

function App:current_rule()
  if self.timer.state ~= "running" or not self.att then return nil end
  local split = self.list.splits[model.current_index(self.att)]
  return split and split.rule
end

function App:on_location(v)
  if type(v) ~= "table" or math.type(v.zone) ~= "integer" then return end
  self.last_zone = v.zone
  if type(v.name) == "string" and v.name ~= "" then self.names_seen[v.zone] = v.name end
  local rule = self:current_rule()
  if rule and rule.kind == "location" and rule.zone == v.zone then
    self:do_split()
    self:render_all()
  end
end

function App:badge_cond(n)
  local ok, res = pcall(self.fb.call, "pokemon.core", "badges")
  if not ok then
    if not self.core_warned then
      self.core_warned = true
      self.fb.log.warn("badge rule: pokemon.core not available: " .. tostring(res))
    end
    return nil
  end
  if type(res) ~= "table" then return nil end
  if type(res.flags) == "table" and res.flags[n] ~= nil then return res.flags[n] == true end
  return type(res.count) == "number" and res.count >= n
end

function App:autosplit()
  local rule = self:current_rule()
  if not rule or not self.rule_state then return false end
  if rule.kind == "memory" then
    return rules.step_memory(self.fb, self.rule_state)
  elseif rule.kind == "badge" and self.ticks % BADGE_POLL_TICKS == 0 then
    local cond = self:badge_cond(rule.n)
    if cond ~= nil then return rules.feed_cond(self.rule_state, cond) end
  end
  return false
end

-- Tick ----------------------------------------------------------------------------------------------------

function App:tick(frame)
  self.last_frame = frame
  self.ticks = self.ticks + 1
  self.timer:update(frame, self.fb.clock())
  local changed = false
  if self.timer.state == "running" and self:autosplit() then
    self:do_split()
    changed = true
  end
  local st = self.timer.state
  if st == "running" or changed then
    self:render_hud()
    if changed or self.ticks % PANEL_REFRESH_TICKS == 0 then
      self:render_panel()
      if self.tab == 1 then self:render_screen() end
    end
  end
end

-- View model ----------------------------------------------------------------------------------------------

function App:vm()
  local list, att = self.list, self.att
  local vm = { has_game = list ~= nil, state = self.timer.state, rows = {}, attempts = 0, completed = 0 }
  if not list then return vm end
  local set = model.set(list)
  vm.timing = list.timing
  vm.main_ms = self.timer:ms(list.timing, list.fps)
  vm.alt_timing = list.timing == "game" and "real" or "game"
  if vm.state ~= "idle" then vm.alt_ms = self.timer:ms(vm.alt_timing, list.fps) end
  vm.attempts, vm.completed = list.attempts, list.completed
  vm.pb_total = set.pb and set.pb.total or nil
  vm.sob = model.sum_of_best(list)
  vm.result = self.result
  local results = att and att.results or {}
  local active = vm.state == "running" or vm.state == "paused"
  local cur = att and model.current_index(att) or 1
  local last_done
  for i, s in ipairs(list.splits) do
    local r = results[i]
    local row = { id = s.id, name = s.name, current = active and i == cur, skipped = r and r.skipped or false,
      time = r and r.time or nil, pb = set.pb and set.pb.times[s.id] or nil, gold = set.golds[s.id],
      rule_text = rules.summary(s.rule) }
    if row.time and row.pb then row.delta = row.time - row.pb end
    if row.time then last_done = i end
    vm.rows[#vm.rows + 1] = row
  end
  if active and list.splits[cur] then
    vm.cur_name = list.splits[cur].name
    local pbc = vm.rows[cur].pb
    if pbc and vm.main_ms > pbc then
      vm.delta = vm.main_ms - pbc
    elseif last_done then
      vm.delta = vm.rows[last_done].delta
    end
  elseif vm.state == "finished" and self.result and self.result.old_total then
    vm.delta = self.result.total - self.result.old_total
  end
  if last_done then
    vm.prev = { name = vm.rows[last_done].name, seg = model.segments(list, att)[last_done],
      delta = vm.rows[last_done].delta, gold = model.is_gold(list, att, last_done) }
  end
  return vm
end

-- Rendering -----------------------------------------------------------------------------------------------

function App:set_if_changed(slot, tree)
  local key = util.ser(tree)
  if self.shown[slot] == key then return end
  self.shown[slot] = key
  self.fb.ui.set(slot, tree)
end

function App:render_hud()
  if not self.list then return end
  self:set_if_changed("hud", views.hud(self:vm(), self.T))
end

function App:render_panel()
  self:set_if_changed("panel", views.panel(self:vm(), self.T))
end

function App:editor_state()
  local locked = self.timer.state == "running" or self.timer.state == "paused"
  local hint
  if self.draft and self.draft.kind == "location" then
    local zone = tonumber(self.draft.zone or "")
    local name = zone and self.names_seen[zone]
    if name then hint = name end
  end
  local core_available = false
  if self.list then core_available = self.core_checked == true end
  return { list = self.list, tab = self.tab, locked = locked, draft = self.draft, import_text = self.import_text,
    import_error = self.import_error, export_text = self.list and textio.export(self.list) or "",
    zone_hint = hint, core_available = core_available }
end

function App:render_screen()
  self:set_if_changed("screen", views.screen(self:vm(), self.T, self:editor_state()))
end

function App:render_all()
  self:render_hud()
  self:render_panel()
  self:render_screen()
end

-- Actions -------------------------------------------------------------------------------------------------

local function structure_locked(self)
  local st = self.timer.state
  return st == "running" or st == "paused"
end

local function mutate(self, fn)
  if not self.list then return false end
  local ok = fn(self.list)
  if ok ~= false then self:save() end
  return ok ~= false
end

local function new_draft(self, id)
  local split
  for _, s in ipairs(self.list.splits) do
    if s.id == id then split = s end
  end
  if not split then return nil end
  local r = split.rule
  local d = { id = id, kind = "none", size = "u8", cmp = "=" }
  if r then
    d.kind = r.kind
    if r.kind == "memory" then
      d.addr, d.size, d.cmp = string.format("0x%X", r.addr), r.size, r.cmp
      d.value = r.value ~= nil and tostring(r.value) or ""
    elseif r.kind == "badge" then
      d.badge = tostring(r.n)
    elseif r.kind == "location" then
      d.zone = tostring(r.zone)
    end
  end
  return d
end

local function draft_rule(d)
  if d.kind == "none" then return true, nil end
  local function int(s)
    local n = tonumber(s)
    return n and math.type(n) == "integer" and n or nil
  end
  if d.kind == "memory" then
    local addr = int(d.addr)
    if not addr then return false, "addr" end
    local rule = { kind = "memory", addr = addr, size = d.size, cmp = d.cmp }
    if d.cmp ~= "changed" then
      rule.value = int(d.value)
      if rule.value == nil then return false, "value" end
    end
    return model.normalize_rule(rule)
  elseif d.kind == "badge" then
    return model.normalize_rule({ kind = "badge", n = int(d.badge) })
  elseif d.kind == "location" then
    return model.normalize_rule({ kind = "location", zone = int(d.zone) })
  end
  return false, "kind"
end

local function current_zone(self)
  if self.last_zone then return self.last_zone end
  local ok, loc = pcall(self.fb.call, "pokemon.core", "location")
  if ok and type(loc) == "table" and math.type(loc.zone) == "integer" then
    if type(loc.name) == "string" then self.names_seen[loc.zone] = loc.name end
    return loc.zone
  end
  return nil
end

local H = {}

function H.split(self) self:split_key() end
function H.undo(self) self:undo() end
function H.skip(self) self:skip() end
function H.reset(self) self:reset() end
function H.pause(self) self:pause() end
function H.open(self)
  if self.fb.ui.open then self.fb.ui.open("screen") end
end
function H.tab(self, v)
  if math.type(v) == "integer" and v >= 1 and v <= 3 then self.tab = v end
end
function H.timing(self, v)
  if structure_locked(self) or (v ~= "game" and v ~= "real") then return end
  mutate(self, function(l) l.timing = v end)
end
function H.fps(self, v)
  local n = tonumber(v)
  if structure_locked(self) or not n or n < 1 or n > 240 then return end
  mutate(self, function(l) l.fps = n end)
end
function H.add(self, v)
  if structure_locked(self) then return end
  local id, why = nil, nil
  mutate(self, function(l)
    id, why = model.add(l, v)
    return id ~= nil
  end)
  if not id and why == "full" then
    self:notify("warning", self.T("edit.full.title"), self.T("edit.full.text", { max = model.MAX_SPLITS }))
  end
end
function H.move_up(self, v)
  if structure_locked(self) then return end
  mutate(self, function(l) return model.move(l, v, -1) end)
end
function H.move_down(self, v)
  if structure_locked(self) then return end
  mutate(self, function(l) return model.move(l, v, 1) end)
end
function H.delete(self, v)
  if structure_locked(self) then return end
  if self.draft and self.draft.id == v then self.draft = nil end
  mutate(self, function(l) return model.delete(l, v) end)
end
function H.rule_edit(self, v)
  if self.list then self.draft = new_draft(self, v) end
end
function H.rule_kind(self, v)
  if self.draft and (v == "none" or v == "memory" or v == "badge" or v == "location") then
    self.draft.kind, self.draft.error = v, nil
    if v == "badge" then self.core_checked = pcall(self.fb.call, "pokemon.core", "badges") end
  end
end
local function draft_field(name)
  return function(self, v)
    if self.draft then
      self.draft[name] = tostring(v or "")
      self.draft.error = nil
    end
  end
end
H.rule_addr = draft_field("addr")
H.rule_value = draft_field("value")
H.rule_badge = draft_field("badge")
H.rule_zone = draft_field("zone")
function H.rule_size(self, v)
  if self.draft and model.SIZES[v] then self.draft.size = v end
end
function H.rule_cmp(self, v)
  if self.draft then self.draft.cmp = v end
end
function H.rule_zone_now(self)
  if not self.draft then return end
  local zone = current_zone(self)
  if zone then
    self.draft.zone = tostring(zone)
    self.draft.error = nil
  else
    self.draft.error = "no_zone"
  end
end
function H.rule_save(self)
  local d = self.draft
  if not d then return end
  local ok, rule = draft_rule(d)
  if not ok then
    d.error = rule
    return
  end
  mutate(self, function(l) return model.set_rule(l, d.id, rule) end)
  self.draft = nil
  if self.timer.state == "running" then self:arm() end
end
function H.rule_cancel(self) self.draft = nil end
function H.import_text(self, v)
  self.import_text = tostring(v or "")
  self.import_error = nil
end
function H.export_view() end
function H.import_apply(self)
  if structure_locked(self) or not self.list then return end
  local list, code, line = textio.import(self.import_text or "", { timing = self.list.timing, fps = self.list.fps })
  if not list then
    self.import_error = self.T("import.err." .. code, { line = line })
    return
  end
  list.attempts = math.max(list.attempts, 0)
  self.list = list
  self.timer:reset()
  self.att, self.result, self.backup = nil, nil, nil
  self.draft, self.import_error = nil, nil
  self:save()
  self.tab = 2
end

local PREFIX = {}
function PREFIX.rename(self, id, v)
  mutate(self, function(l) return model.rename(l, id, v) end)
end

function App:action(action, value, slot)
  self:sync()
  local h = H[action]
  if h then
    h(self, value)
  else
    local name, arg = tostring(action):match("^(%a+):(.+)$")
    if name and PREFIX[name] then PREFIX[name](self, arg, value) end
  end
  if action == "import_text" or action == "export_view" then return end -- typing: do not redraw under the cursor
  self:render_all()
end

App.default_fps = default_fps

return App

end
__mod["fmt"] = function(...)
-- Time formatting. All inputs are integer milliseconds.
local M = {}

--- "1:02:03.45" (hours only when needed), "-" for nil. Negative values get a leading "-".
function M.time(ms)
  if ms == nil then return "-" end
  local neg = ms < 0
  if neg then ms = -ms end
  local cs = ms // 10
  local h = cs // 360000
  local m = (cs // 6000) % 60
  local s = (cs // 100) % 60
  local c = cs % 100
  local out
  if h > 0 then
    out = string.format("%d:%02d:%02d.%02d", h, m, s, c)
  else
    out = string.format("%d:%02d.%02d", m, s, c)
  end
  return (neg and "-" or "") .. out
end

--- Signed difference: "+1.23", "-0:12.30"; "" for nil.
function M.delta(ms)
  if ms == nil then return "" end
  local sign = ms < 0 and "-" or "+"
  local a = math.abs(ms)
  local body
  if a < 60000 then
    body = string.format("%d.%02d", a // 1000, (a % 1000) // 10)
  else
    body = M.time(a)
  end
  return sign .. body
end

return M

end
__mod["main"] = function(...)
-- Entry module of the Splits plugin.
local App = require("controller")

fb.log.info(fb.i18n.t("loaded", { version = (fb.plugin and fb.plugin.version) or "?" }))
App.new(fb):start()

end
__mod["model"] = function(...)
-- Split list, personal best, best segments and one attempt. Pure data logic, no fb.
--
-- list = { v = 1, timing = "game"|"real", fps = number, next_id = n, attempts = n, completed = n,
--          splits = { { id, name, rule? }, ... },
--          sets = { game = { pb = { total, times = { [id] = cumulative ms } }, golds = { [id] = ms } }, real = {...} } }
-- Times are per timing method, so switching between game and real time never mixes them.
-- attempt = { results = { { time = cumulative ms } | { skipped = true }, ... } } (one entry per passed split)
local util = require("util")

local M = {}
M.MAX_SPLITS = 100
M.SIZES = { u8 = 1, u16 = 2, u32 = 4 }
M.MAX = { u8 = 0xFF, u16 = 0xFFFF, u32 = 0xFFFFFFFF }
M.CMPS = { "=", "!=", ">", ">=", "<", "<=", "changed" }
M.SIZE_LIST = { "u8", "u16", "u32" }
local CMP = {}
for _, c in ipairs(M.CMPS) do CMP[c] = true end

local function is_int(v) return math.type(v) == "integer" end

function M.new_list(timing, fps)
  return { v = 1, timing = timing or "game", fps = fps or 60, next_id = 1, attempts = 0, completed = 0,
           splits = {}, sets = {} }
end

--- The data set of the active timing method (created on demand).
function M.set(list)
  local s = list.sets[list.timing]
  if not s then
    s = { golds = {} }
    list.sets[list.timing] = s
  end
  s.golds = s.golds or {}
  return s
end

function M.index_of(list, id)
  for i, s in ipairs(list.splits) do
    if s.id == id then return i end
  end
  return nil
end

--- Normalizes an autosplit rule. Returns true, rule (nil for "no rule") or false, error code.
function M.normalize_rule(r)
  if r == nil or r == false then return true, nil end
  if type(r) ~= "table" then return false, "kind" end
  if r.kind == "memory" then
    if not is_int(r.addr) or r.addr < 0 or r.addr > 0xFFFFFFFF then return false, "addr" end
    if not M.SIZES[r.size] then return false, "size" end
    local cmp = r.cmp == "==" and "=" or r.cmp
    if not CMP[cmp] then return false, "cmp" end
    local out = { kind = "memory", addr = r.addr, size = r.size, cmp = cmp }
    if cmp ~= "changed" then
      if not is_int(r.value) or r.value < 0 or r.value > M.MAX[r.size] then return false, "value" end
      out.value = r.value
    end
    return true, out
  elseif r.kind == "badge" then
    if not is_int(r.n) or r.n < 1 or r.n > 8 then return false, "badge" end
    return true, { kind = "badge", n = r.n }
  elseif r.kind == "location" then
    if not is_int(r.zone) or r.zone < 0 or r.zone > 0xFFFFFFFF then return false, "zone" end
    return true, { kind = "location", zone = r.zone }
  end
  return false, "kind"
end

--- Validates stored data and returns a clean list, or nil when it is not a list at all.
function M.sanitize(v)
  if type(v) ~= "table" or v.v ~= 1 or type(v.splits) ~= "table" then return nil end
  local timing = v.timing == "real" and "real" or "game"
  local fps = type(v.fps) == "number" and v.fps >= 1 and v.fps <= 240 and v.fps or 60
  local list = M.new_list(timing, fps)
  local seen = {}
  for _, s in ipairs(v.splits) do
    if type(s) == "table" and type(s.id) == "string" and not seen[s.id] and #list.splits < M.MAX_SPLITS then
      local name = util.clean_name(s.name)
      if name ~= "" then
        seen[s.id] = true
        local ok, rule = M.normalize_rule(s.rule)
        list.splits[#list.splits + 1] = { id = s.id, name = name, rule = ok and rule or nil }
      end
    end
  end
  local top = 0
  for id in pairs(seen) do
    local n = tonumber(id:match("^s(%d+)$"))
    if n and n > top then top = n end
  end
  list.next_id = math.max(top + 1, is_int(v.next_id) and v.next_id or 1)
  list.attempts = is_int(v.attempts) and v.attempts >= 0 and v.attempts or 0
  list.completed = is_int(v.completed) and v.completed >= 0 and v.completed or 0
  for _, key in ipairs({ "game", "real" }) do
    local src = type(v.sets) == "table" and v.sets[key]
    if type(src) == "table" then
      local set = { golds = {} }
      if type(src.golds) == "table" then
        for id, ms in pairs(src.golds) do
          if type(id) == "string" and is_int(ms) and ms > 0 then set.golds[id] = ms end
        end
      end
      local pb = src.pb
      if type(pb) == "table" and is_int(pb.total) and pb.total > 0 and type(pb.times) == "table" then
        set.pb = { total = pb.total, times = {} }
        for id, ms in pairs(pb.times) do
          if type(id) == "string" and is_int(ms) and ms >= 0 then set.pb.times[id] = ms end
        end
      end
      list.sets[key] = set
    end
  end
  return list
end

-- Editing -------------------------------------------------------------------------------------------------

--- Adds a split at the end (or at `index`). Returns the id, or nil, "full" | "name".
function M.add(list, name, rule, index)
  name = util.clean_name(name)
  if name == "" then return nil, "name" end
  if #list.splits >= M.MAX_SPLITS then return nil, "full" end
  local id = "s" .. list.next_id
  list.next_id = list.next_id + 1
  local entry = { id = id, name = name, rule = rule }
  table.insert(list.splits, index or (#list.splits + 1), entry)
  return id
end

function M.rename(list, id, name)
  local i = M.index_of(list, id)
  name = util.clean_name(name)
  if not i or name == "" then return false end
  list.splits[i].name = name
  return true
end

function M.delete(list, id)
  local i = M.index_of(list, id)
  if not i then return false end
  table.remove(list.splits, i)
  for _, set in pairs(list.sets) do
    if set.pb then set.pb.times[id] = nil end
    if set.golds then set.golds[id] = nil end
  end
  return true
end

--- dir = -1 (up) or 1 (down).
function M.move(list, id, dir)
  local i = M.index_of(list, id)
  if not i then return false end
  local j = i + dir
  if j < 1 or j > #list.splits then return false end
  list.splits[i], list.splits[j] = list.splits[j], list.splits[i]
  return true
end

function M.set_rule(list, id, rule)
  local i = M.index_of(list, id)
  if not i then return false end
  local ok, norm = M.normalize_rule(rule)
  if not ok then return false end
  list.splits[i].rule = norm
  return true
end

-- Attempt -------------------------------------------------------------------------------------------------

function M.new_attempt() return { results = {} } end

--- Index of the split the attempt is on; > #splits when every split has a result.
function M.current_index(att) return #att.results + 1 end

function M.is_done(list, att) return #att.results >= #list.splits end

--- Records a split at cumulative time `ms`. Returns true when this was the last split.
function M.record_split(list, att, ms)
  if M.is_done(list, att) then return false end
  att.results[#att.results + 1] = { time = ms }
  return M.is_done(list, att)
end

--- Skips the current split (never the last one). Returns true when skipped.
function M.record_skip(list, att)
  local i = M.current_index(att)
  if i >= #list.splits then return false end
  att.results[i] = { skipped = true }
  return true
end

--- Removes the last result. Returns true when there was one.
function M.undo(att)
  if #att.results == 0 then return false end
  att.results[#att.results] = nil
  return true
end

--- Segment times by split index. A segment after a skipped split would span several splits, so it has none.
function M.segments(list, att)
  local segs = {}
  local prev_cum, prev_ok = 0, true
  for i, r in ipairs(att.results) do
    if r.skipped then
      prev_ok = false
    else
      if prev_ok then segs[i] = r.time - prev_cum end
      prev_cum, prev_ok = r.time, true
    end
  end
  return segs
end

--- Personal best cumulative time of a split (nil without PB or when that PB skipped it).
function M.pb_time(list, id)
  local pb = M.set(list).pb
  return pb and pb.times[id] or nil
end

--- True when the segment at index `i` of the attempt beats the stored best segment (or there is none yet).
function M.is_gold(list, att, i)
  local seg = M.segments(list, att)[i]
  if not seg or seg <= 0 then return false end
  local best = M.set(list).golds[list.splits[i].id]
  return best == nil or seg < best
end

--- Sum of the best segments, or nil when a split has none.
function M.sum_of_best(list)
  if #list.splits == 0 then return nil end
  local golds, total = M.set(list).golds, 0
  for _, s in ipairs(list.splits) do
    if not golds[s.id] then return nil end
    total = total + golds[s.id]
  end
  return total
end

--- Applies the attempt to the list: best segments always, the personal best when the run is finished and faster.
--- Returns { pb = bool, old_total = n|nil, total = n|nil, golds = { ids } }.
function M.commit(list, att, finished)
  local set = M.set(list)
  local info = { pb = false, golds = {} }
  local segs = M.segments(list, att)
  for i = 1, #att.results do
    local seg = segs[i]
    local id = list.splits[i] and list.splits[i].id
    if id and seg and seg > 0 and (set.golds[id] == nil or seg < set.golds[id]) then
      set.golds[id] = seg
      info.golds[#info.golds + 1] = id
    end
  end
  if finished then
    local last = att.results[#list.splits]
    if last and last.time then
      info.total = last.time
      list.completed = list.completed + 1
      info.old_total = set.pb and set.pb.total or nil
      if not set.pb or last.time < set.pb.total then
        local times = {}
        for i, r in ipairs(att.results) do
          if r.time and list.splits[i] then times[list.splits[i].id] = r.time end
        end
        set.pb = { total = last.time, times = times }
        info.pb = true
      end
    end
  end
  return info
end

return M

end
__mod["rules"] = function(...)
-- Autosplit rule evaluation for the current split. Pure except for the memory reads through `fb`.
--
-- A condition that is already true when a split becomes current does not fire; it fires on the next change
-- from false to true. This keeps a flag that is still set from the previous split from splitting again.
local model = require("model")

local M = {}

function M.compare(op, a, b)
  if op == "=" then return a == b
  elseif op == "!=" then return a ~= b
  elseif op == ">" then return a > b
  elseif op == ">=" then return a >= b
  elseif op == "<" then return a < b
  elseif op == "<=" then return a <= b
  end
  return false
end

--- Starts watching for `rule` (nil = no rule). Returns the evaluation state, or nil without a rule.
function M.arm(fb, rule)
  if not rule then
    fb.memory.unwatch("rule")
    return nil
  end
  if rule.kind == "memory" then
    fb.memory.watch("rule", rule.addr, model.SIZES[rule.size])
  else
    fb.memory.unwatch("rule")
  end
  return { rule = rule }
end

function M.disarm(fb)
  fb.memory.unwatch("rule")
end

--- Feeds a boolean condition; true exactly once, on the change from false to true after the baseline.
function M.feed_cond(st, cond)
  if st.base == nil then
    st.base = cond
    return false
  end
  local fired = cond and not st.base
  st.base = cond
  return fired
end

--- One evaluation step of a memory rule. Returns true when the split should fire.
function M.step_memory(fb, st)
  local rule = st.rule
  local v = fb.memory[rule.size](rule.addr)
  if v == nil then return false end
  if rule.cmp == "changed" then
    if st.prev == nil then
      st.prev = v
      return false
    end
    local changed = v ~= st.prev
    st.prev = v
    return changed
  end
  return M.feed_cond(st, M.compare(rule.cmp, v, rule.value))
end

--- Short human-readable summary of a rule (no names, only ids and numbers).
function M.summary(rule)
  if not rule then return nil end
  if rule.kind == "memory" then
    local s = string.format("0x%X %s %s", rule.addr, rule.size, rule.cmp)
    if rule.cmp ~= "changed" then s = s .. " " .. rule.value end
    return s
  elseif rule.kind == "badge" then
    return "badge " .. rule.n
  elseif rule.kind == "location" then
    return "zone " .. rule.zone
  end
  return nil
end

return M

end
__mod["textio"] = function(...)
-- Text format for exporting and importing a split list (shown in a textarea).
--
--   # comment
--   @timing game          header lines: @timing (game|real), @fps, @attempts, @completed, @pb (total, ms)
--   Name | rule | PB | best segment
--
-- rule: "-" (none), "mem <addr> <u8|u16|u32> <cmp> [value]", "badge <1..8>", "zone <id>"
-- PB is the cumulative time of the split in the personal best run (ms), best segment in ms; "-" when unknown.
-- A line without "|" is just a split name, so a pasted list of names works.
local model = require("model")
local util = require("util")

local M = {}

local function toint(s)
  local n = tonumber(s)
  if n and math.type(n) == "integer" then return n end
  return nil
end

--- Parses rule text. Returns true, rule (nil for none) or false, error code.
function M.parse_rule(s)
  s = util.trim(s or "")
  if s == "" or s == "-" then return true, nil end
  local tok = {}
  for w in s:gmatch("%S+") do tok[#tok + 1] = w end
  local kind = tok[1]:lower()
  if kind == "mem" then
    if #tok < 4 or #tok > 5 then return false, "rule" end
    local rule = { kind = "memory", addr = toint(tok[2]), size = tok[3]:lower(), cmp = tok[4] }
    if tok[5] then
      rule.value = toint(tok[5])
      if rule.value == nil then return false, "value" end
    end
    return model.normalize_rule(rule)
  elseif kind == "badge" then
    if #tok ~= 2 then return false, "rule" end
    return model.normalize_rule({ kind = "badge", n = toint(tok[2]) })
  elseif kind == "zone" then
    if #tok ~= 2 then return false, "rule" end
    return model.normalize_rule({ kind = "location", zone = toint(tok[2]) })
  end
  return false, "rule"
end

function M.rule_to_text(rule)
  if not rule then return "-" end
  if rule.kind == "memory" then
    local base = string.format("mem 0x%X %s %s", rule.addr, rule.size, rule.cmp)
    if rule.cmp ~= "changed" then base = base .. " " .. tostring(rule.value) end
    return base
  elseif rule.kind == "badge" then
    return "badge " .. rule.n
  elseif rule.kind == "location" then
    return "zone " .. rule.zone
  end
  return "-"
end

--- Exports the list (the data of its active timing method).
function M.export(list)
  local set = model.set(list)
  local out = { "# Splits 1 - Name | rule | PB (cumulative ms) | best segment (ms)" }
  out[#out + 1] = "@timing " .. list.timing
  out[#out + 1] = "@fps " .. string.format("%.4f", list.fps):gsub("0+$", ""):gsub("%.$", "")
  out[#out + 1] = "@attempts " .. list.attempts
  out[#out + 1] = "@completed " .. list.completed
  if set.pb then out[#out + 1] = "@pb " .. set.pb.total end
  for _, s in ipairs(list.splits) do
    local pb = set.pb and set.pb.times[s.id]
    local gold = set.golds[s.id]
    out[#out + 1] = string.format("%s | %s | %s | %s", s.name, M.rule_to_text(s.rule),
      pb and tostring(pb) or "-", gold and tostring(gold) or "-")
  end
  return table.concat(out, "\n")
end

local function opt_ms(s, allow_zero)
  s = util.trim(s or "")
  if s == "" or s == "-" then return true, nil end
  local n = toint(s)
  if not n or n < 0 or (n == 0 and not allow_zero) then return false end
  return true, n
end

--- Imports text. Returns list, or nil, code, line number. Codes: header, number, rule, name, empty, too_many.
--- The list keeps `base` timing/fps defaults (a table { timing, fps }) unless the text sets them.
function M.import(text, base)
  local list = model.new_list(base and base.timing or "game", base and base.fps or 60)
  local set = { golds = {} }
  local pb_total
  local line_no = 0
  for raw in (tostring(text or "") .. "\n"):gmatch("([^\n]*)\n") do
    line_no = line_no + 1
    local line = util.trim((raw:gsub("\r", "")))
    if line ~= "" and line:sub(1, 1) ~= "#" then
      if line:sub(1, 1) == "@" then
        local key, val = line:match("^@(%a+)%s+(.-)$")
        if not key then return nil, "header", line_no end
        key = key:lower()
        if key == "timing" then
          if val ~= "game" and val ~= "real" then return nil, "header", line_no end
          list.timing = val
        elseif key == "fps" then
          local n = tonumber(val)
          if not n or n < 1 or n > 240 then return nil, "number", line_no end
          list.fps = n
        elseif key == "attempts" or key == "completed" then
          local n = toint(val)
          if not n or n < 0 then return nil, "number", line_no end
          list[key] = n
        elseif key == "pb" then
          local n = toint(val)
          if not n or n <= 0 then return nil, "number", line_no end
          pb_total = n
        else
          return nil, "header", line_no
        end
      else
        if #list.splits >= model.MAX_SPLITS then return nil, "too_many", line_no end
        local fields = {}
        if line:find("|", 1, true) then
          for f in (line .. "|"):gmatch("([^|]*)|") do fields[#fields + 1] = f end
        else
          fields[1] = line
        end
        local name = util.clean_name(fields[1])
        if name == "" then return nil, "name", line_no end
        local ok, rule = M.parse_rule(fields[2])
        if not ok then return nil, "rule", line_no end
        local okp, pb = opt_ms(fields[3], true)
        local okg, gold = opt_ms(fields[4], false)
        if not okp or not okg then return nil, "number", line_no end
        local id = model.add(list, name, rule)
        if pb then
          set.pb = set.pb or { total = 0, times = {} }
          set.pb.times[id] = pb
        end
        if gold then set.golds[id] = gold end
      end
    end
  end
  if #list.splits == 0 then return nil, "empty", line_no end
  if set.pb then
    local last = list.splits[#list.splits]
    local total = pb_total or set.pb.times[last.id]
    if total and total > 0 then set.pb.total = total else set.pb = nil end
  end
  list.sets[list.timing] = set
  return list
end

return M

end
__mod["timer"] = function(...)
-- Timer on two clocks: game time (snapshot frames) and real time (fb.clock milliseconds).
-- Pure: the caller passes the latest snapshot frame and the monotonic clock into every call.
-- Game time stops by itself when the snapshot frame stops (the game is paused). A frame number that goes
-- back (reset, loaded state) is a discontinuity: it counts nothing and becomes the new reference.
local T = {}
T.__index = T

function T.new()
  return setmetatable({ state = "idle", frames = 0, real = 0, last_frame = nil, last_now = nil }, T)
end

function T:reset()
  self.state, self.frames, self.real, self.last_frame, self.last_now = "idle", 0, 0, nil, nil
end

--- Adds what happened since the last call. Only a running timer accumulates.
function T:update(frame, now)
  if self.state == "running" then
    if frame ~= nil then
      if self.last_frame ~= nil and frame >= self.last_frame then
        self.frames = self.frames + (frame - self.last_frame)
      end
      self.last_frame = frame
    end
    if now ~= nil and self.last_now ~= nil and now > self.last_now then
      self.real = self.real + (now - self.last_now)
    end
    if now ~= nil then self.last_now = now end
  else
    if frame ~= nil then self.last_frame = frame end
    if now ~= nil then self.last_now = now end
  end
end

function T:start(frame, now)
  self.frames, self.real = 0, 0
  self.last_frame, self.last_now = frame, now
  self.state = "running"
end

function T:pause(frame, now)
  if self.state ~= "running" then return false end
  self:update(frame, now)
  self.state = "paused"
  return true
end

function T:resume(frame, now)
  if self.state ~= "paused" then return false end
  self:update(frame, now) -- not running: only moves the references
  self.state = "running"
  return true
end

--- Freezes the times (finished run).
function T:stop(frame, now)
  if self.state ~= "running" and self.state ~= "paused" then return false end
  self:update(frame, now)
  self.state = "finished"
  return true
end

--- Continues a finished run (undo of the last split); the time in between does not count.
function T:continue(frame, now)
  if self.state ~= "finished" then return false end
  self:update(frame, now)
  self.state = "running"
  return true
end

function T:game_ms(fps)
  return math.floor(self.frames * 1000 / fps + 0.5)
end

function T:real_ms()
  return math.floor(self.real + 0.5)
end

--- Elapsed time in the given timing method ("game" or "real").
function T:ms(timing, fps)
  if timing == "real" then return self:real_ms() end
  return self:game_ms(fps)
end

return T

end
__mod["util"] = function(...)
-- Small helpers shared by the modules.
local M = {}

function M.copy(v)
  if type(v) ~= "table" then return v end
  local c = {}
  for k, x in pairs(v) do c[k] = M.copy(x) end
  return c
end

function M.trim(s)
  return (tostring(s):match("^%s*(.-)%s*$"))
end

--- Split name: control characters become spaces, "|" becomes "/" (the text format uses "|"), trimmed, at most
--- `max` characters (default 60). Returns "" for empty input.
function M.clean_name(s, max)
  max = max or 60
  s = tostring(s or "")
  s = s:gsub("|", "/")
  s = s:gsub("%c", " ")
  s = M.trim(s)
  s = s:gsub("%s+", " ")
  local len = utf8.len(s)
  if len and len > max then
    s = s:sub(1, utf8.offset(s, max + 1) - 1)
  elseif not len and #s > max then
    s = s:sub(1, max)
  end
  return s
end

--- Deterministic string form of a value (sorted keys), to compare trees and states cheaply.
function M.ser(v)
  local tv = type(v)
  if tv == "table" then
    local keys = {}
    for k in pairs(v) do keys[#keys + 1] = k end
    table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
    local out = {}
    for _, k in ipairs(keys) do out[#out + 1] = tostring(k) .. "=" .. M.ser(v[k]) end
    return "{" .. table.concat(out, ",") .. "}"
  elseif tv == "string" then
    return string.format("%q", v)
  end
  return tostring(v)
end

return M

end
__mod["views"] = function(...)
-- Declarative UI trees (HUD, panel, screen) built from a view model. Pure functions, no fb access.
local fmt = require("fmt")
local model = require("model")
local rules = require("rules")

local M = {}

local function tone_of(ms)
  if ms == nil then return nil end
  if ms < 0 then return "ok" end
  if ms > 0 then return "danger" end
  return "neutral"
end

local function text(props)
  props.type = "text"
  return props
end

-- HUD ----------------------------------------------------------------------------------------------------

function M.hud(vm, T)
  local alt
  if vm.state == "paused" then
    alt = T("hud.paused")
  elseif vm.alt_ms ~= nil then
    if vm.alt_timing == "real" then
      alt = T("hud.alt.real", { time = fmt.time(vm.alt_ms) })
    else
      alt = T("hud.alt.game", { time = fmt.time(vm.alt_ms) })
    end
  end
  local top = { text({ id = "time", text = fmt.time(vm.main_ms), style = "value" }) }
  if alt then top[#top + 1] = text({ id = "alt", text = alt, style = "meta" }) end
  local kids = { { type = "row", gap = 8, align = "center", children = top } }

  local name
  if #vm.rows == 0 then
    name = T("hud.no_splits")
  elseif vm.state == "idle" then
    name = T("hud.ready", { name = vm.rows[1].name })
  elseif vm.state == "finished" then
    name = vm.result and vm.result.pb and T("hud.new_pb") or T("hud.finished")
  else
    name = vm.cur_name or "-"
  end
  local line = { text({ id = "split", text = name, style = "body" }) }
  if vm.delta ~= nil then
    line[#line + 1] = text({ id = "delta", text = fmt.delta(vm.delta), style = "body", tone = tone_of(vm.delta) })
  end
  kids[#kids + 1] = { type = "row", gap = 8, align = "center", children = line }

  if vm.prev and vm.state ~= "idle" then
    local p = vm.prev
    local label = T("hud.prev", { name = p.name, time = p.delta ~= nil and fmt.delta(p.delta) or fmt.time(p.seg) })
    if p.gold then label = label .. " " .. T("hud.gold") end
    kids[#kids + 1] = text({ id = "prev", text = label, style = "meta", tone = p.gold and "warning" or tone_of(p.delta) })
  end
  return { type = "column", gap = 4, children = kids }
end

-- Panel --------------------------------------------------------------------------------------------------

-- in_screen: the screen has its own "Edit" tab, so it does not repeat the button that opens the editor.
local function controls(vm, T, in_screen)
  local primary
  if vm.state == "idle" then
    primary = { type = "button", label = T("btn.start"), action = "split", variant = "primary" }
  elseif vm.state == "running" then
    primary = { type = "button", label = T("btn.split"), action = "split", variant = "primary" }
  else
    primary = { type = "button", label = T("btn.split"), action = "split", variant = "secondary" }
  end
  local kids = {
    primary,
    { type = "button", label = T("btn.undo"), action = "undo", variant = "secondary" },
    { type = "button", label = T("btn.skip"), action = "skip", variant = "secondary" },
    { type = "button", label = (vm.state == "paused" and T("btn.resume") or T("btn.pause")), action = "pause", variant = "secondary" },
    -- Reset throws the current attempt away: marked as destructive (no dialog, it is also a hotkey).
    { type = "button", label = T("btn.reset"), action = "reset", variant = "danger" },
  }
  if not in_screen then kids[#kids + 1] = { type = "button", label = T("btn.edit"), action = "open", variant = "quiet" } end
  return { type = "grid", gap = 8, columns = 3, children = kids }
end

function M.panel(vm, T)
  if not vm.has_game then
    return { type = "empty", title = T("empty.no_game.title"), text = T("empty.no_game.text") }
  end
  if #vm.rows == 0 then
    return { type = "column", gap = 12, children = {
      { type = "empty", title = T("empty.no_splits.title"), text = T("empty.no_splits.text"),
        action_label = T("btn.edit"), action = "open" },
    } }
  end
  local rows = {}
  for _, r in ipairs(vm.rows) do
    local cells = {
      (r.current and "> " or "") .. r.name,
      r.time and fmt.time(r.time) or (r.skipped and "-" or ""),
      r.delta ~= nil and fmt.delta(r.delta) or "",
    }
    rows[#rows + 1] = { cells = cells }
  end
  local hud = M.hud(vm, T)
  return { type = "column", gap = 12, children = {
    hud,
    controls(vm, T),
    { type = "table", columns = { T("col.split"), T("col.time"), T("col.delta") }, rows = rows },
  } }
end

-- Screen -------------------------------------------------------------------------------------------------

local function stat(id, label, value)
  return { type = "stat", id = id, label = label, value = value }
end

local function run_page(vm, T)
  local rows = {}
  for _, r in ipairs(vm.rows) do
    rows[#rows + 1] = { cells = {
      (r.current and "> " or "") .. r.name,
      r.time and fmt.time(r.time) or "",
      r.delta ~= nil and fmt.delta(r.delta) or "",
      r.pb and fmt.time(r.pb) or "-",
      r.gold and fmt.time(r.gold) or "-",
      r.rule_text or "",
    } }
  end
  local kids = {
    { type = "grid", gap = 12, columns = 4, children = {
      stat("st_attempts", T("stat.attempts"), vm.attempts),
      stat("st_completed", T("stat.completed"), vm.completed),
      stat("st_pb", T("stat.pb"), vm.pb_total and fmt.time(vm.pb_total) or "-"),
      stat("st_sob", T("stat.sob"), vm.sob and fmt.time(vm.sob) or "-"),
    } },
    controls(vm, T, true),
  }
  if #rows == 0 then
    kids[#kids + 1] = { type = "empty", title = T("empty.no_splits.title"), text = T("empty.no_splits.text") }
  else
    kids[#kids + 1] = { type = "table",
      columns = { T("col.split"), T("col.time"), T("col.delta"), T("col.pb"), T("col.best"), T("col.rule") },
      rows = rows }
  end
  return { type = "column", gap = 16, children = kids }
end

local function opt(value, label) return { value = value, label = label } end

local FPS_OPTIONS = { "60", "59.83", "59.73" }

local function fps_value(fps)
  for _, o in ipairs(FPS_OPTIONS) do
    if math.abs(tonumber(o) - fps) < 0.005 then return o end
  end
  return nil
end

local function rule_section(ed, T)
  local d = ed.draft
  local name = "?"
  for _, s in ipairs(ed.list.splits) do
    if s.id == d.id then name = s.name end
  end
  local kids = {
    { type = "select", id = "rule_kind", action = "rule_kind", selected = d.kind, options = {
      opt("none", T("rule.kind.none")), opt("memory", T("rule.kind.memory")),
      opt("badge", T("rule.kind.badge")), opt("location", T("rule.kind.location")) } },
  }
  if d.kind == "memory" then
    local cmps = {}
    for _, c in ipairs(model.CMPS) do cmps[#cmps + 1] = opt(c, c == "changed" and T("rule.cmp.changed") or c) end
    local sizes = {}
    for _, s in ipairs(model.SIZE_LIST) do sizes[#sizes + 1] = opt(s, s) end
    kids[#kids + 1] = { type = "textfield", id = "rule_addr", action = "rule_addr", text = d.addr or "",
      placeholder = T("rule.addr") }
    kids[#kids + 1] = { type = "row", gap = 8, align = "center", children = {
      { type = "select", id = "rule_size", action = "rule_size", selected = d.size, options = sizes },
      { type = "select", id = "rule_cmp", action = "rule_cmp", selected = d.cmp, options = cmps },
    } }
    if d.cmp ~= "changed" then
      kids[#kids + 1] = { type = "textfield", id = "rule_value", action = "rule_value", text = d.value or "",
        placeholder = T("rule.value") }
    end
  elseif d.kind == "badge" then
    kids[#kids + 1] = { type = "textfield", id = "rule_badge", action = "rule_badge", text = d.badge or "",
      placeholder = T("rule.badge") }
    if not ed.core_available then
      kids[#kids + 1] = text({ text = T("rule.badge.needs_core"), style = "meta", tone = "warning" })
    end
  elseif d.kind == "location" then
    kids[#kids + 1] = { type = "textfield", id = "rule_zone", action = "rule_zone", text = d.zone or "",
      placeholder = T("rule.zone") }
    kids[#kids + 1] = { type = "button", id = "rule_zone_now", label = T("rule.zone_now"), action = "rule_zone_now",
      variant = "secondary" }
    if ed.zone_hint then kids[#kids + 1] = text({ text = ed.zone_hint, style = "meta" }) end
  end
  if d.error then
    kids[#kids + 1] = text({ id = "rule_error", text = T("rule.err." .. d.error), tone = "danger", style = "body" })
  end
  kids[#kids + 1] = { type = "row", gap = 8, children = {
    { type = "button", label = T("btn.save"), action = "rule_save", variant = "primary" },
    { type = "button", label = T("btn.cancel"), action = "rule_cancel", variant = "quiet" },
  } }
  return { type = "section", id = "rule_editor", title = T("rule.title", { name = name }), children = kids }
end

local function edit_page(vm, T, ed)
  local list = ed.list
  local kids = {}
  local fps_opts = {}
  for _, o in ipairs(FPS_OPTIONS) do fps_opts[#fps_opts + 1] = opt(o, T("fps_" .. o:gsub("%.", ""))) end
  kids[#kids + 1] = { type = "section", title = T("edit.timing"), children = {
    { type = "segmented", id = "timing", action = "timing", selected = list.timing, options = {
      opt("game", T("timing.game")), opt("real", T("timing.real")) } },
    text({ text = T("timing.hint"), style = "meta" }),
    { type = "select", id = "fps", action = "fps", selected = fps_value(list.fps), options = fps_opts },
    text({ text = T("fps.hint"), style = "meta" }),
  } }

  local rows = {}
  if #list.splits == 0 then
    rows[#rows + 1] = { type = "empty", title = T("empty.no_splits.title"), text = T("empty.no_splits.text") }
  end
  for i, s in ipairs(list.splits) do
    local row = { text({ text = tostring(i), style = "meta" }),
      { type = "textfield", id = "name_" .. s.id, action = "rename:" .. s.id, text = s.name } }
    row[#row + 1] = { type = "button", id = "rule_btn_" .. s.id, label = rules.summary(s.rule) or T("btn.rule"),
      action = "rule_edit", value = s.id, variant = s.rule and "secondary" or "quiet" }
    if not ed.locked then
      row[#row + 1] = { type = "button", id = "up_" .. s.id, label = "^", action = "move_up", value = s.id, variant = "quiet" }
      row[#row + 1] = { type = "button", id = "down_" .. s.id, label = "v", action = "move_down", value = s.id, variant = "quiet" }
      row[#row + 1] = { type = "button", id = "del_" .. s.id, label = "x", action = "delete", value = s.id, variant = "danger",
        confirm = { title = T("confirm.delete.title", { name = s.name }), text = T("confirm.delete.text"), danger = true } }
    end
    rows[#rows + 1] = { type = "row", gap = 8, align = "center", children = row }
  end
  local split_kids = rows
  if ed.locked then
    table.insert(split_kids, 1, text({ text = T("edit.locked"), style = "meta", tone = "warning" }))
  else
    split_kids[#split_kids + 1] = { type = "textfield", id = "add", action = "add", placeholder = T("edit.add") }
  end
  kids[#kids + 1] = { type = "section", title = T("edit.splits"), children = split_kids }
  if ed.draft then kids[#kids + 1] = rule_section(ed, T) end
  return { type = "column", gap = 16, children = kids }
end

local function io_page(vm, T, ed)
  local import_area = { type = "textarea", id = "import_area", action = "import_text", value = ed.import_text or "",
    lines = 8, mono = true, placeholder = T("io.import.placeholder") }
  if ed.import_error then import_area.error = ed.import_error end
  return { type = "column", gap = 16, children = {
    { type = "section", title = T("io.export"), children = {
      text({ text = T("io.export.hint"), style = "meta" }),
      { type = "textarea", id = "export_area", action = "export_view", value = ed.export_text, lines = 10, mono = true },
    } },
    { type = "section", title = T("io.import"), children = {
      text({ text = T("io.import.hint"), style = "meta" }),
      import_area,
      { type = "button", id = "import_apply", label = T("io.import.apply"), action = "import_apply", variant = "primary",
        confirm = { title = T("io.import.confirm.title"), text = T("io.import.confirm.text"), danger = true } },
      ed.locked and text({ text = T("edit.locked"), style = "meta", tone = "warning" }) or nil,
    } },
  } }
end

function M.screen(vm, T, ed)
  if not vm.has_game then
    return { type = "empty", title = T("empty.no_game.title"), text = T("empty.no_game.text") }
  end
  local tab = ed.tab or 1
  return { type = "tabs", id = "tabs", action = "tab", selected = tab,
    tabs = { T("tab.run"), T("tab.edit"), T("tab.io") },
    children = { run_page(vm, T), edit_page(vm, T, ed), io_page(vm, T, ed) } }
end

return M

end
require("main")
